-- 142 — Set asiatici e My First Battle nel catalogo, letti da Cardmarket (13/11/2026).
-- Ogni pagina Cardmarket è una carta del set, anche le versioni con lo stesso numero (V1, V2… fino a V9
-- nei Gem Pack): decisione di Claudio del 13/11, "tutte le versioni". Numero di catalogo progressivo,
-- codice della carta in "codice" ("SV2A 009", "CBB1C 07", "M-P 022"; "MFB" e "EXP" senza numero) e
-- pagina in cardmarket_url. Il widget Set riconosce le vostre carte dalla pagina, poi dal codice se nel
-- set è unico (ui/set-motore.ui.js, stessa PR).
--
-- Letto il 13/11/2026 col Chrome di Claudio: 59 espansioni Cardmarket, 6240 pagine. Le 58 asiatiche sono
-- quelle in cui il gruppo ha carte (decisione: "tutti i ~55 del gruppo"), più My First Battle ("Prima
-- Lotta": 48 pagine senza numero, un masterset solo, non diviso per mazzo). Per ogni espansione il
-- numero di pagine lette è uguale al totale di Cardmarket.
-- FUORI DA QUESTO FILE: Shiny Star V (S4A), Shiny Treasure ex (SV4A) e le promo SM-P, S-P, XY-P.
-- Hanno più di 300 pagine e Cardmarket ne mostra al massimo 300 per elenco: arrivano con la 143,
-- letti in ordine di numero dai due capi. I loro set della 131 restano com'erano (senza carte).
-- Un set per ogni lingua in cui il gruppo ha carte (66 set, 29 nuovi; 37 dei 40 della 131 prendono
-- le carte e il totale vero). Righe nel catalogo: 8093.
-- Miniature: nessuna (Cardmarket non lascia usare le sue foto da fuori); arrivano dalle vostre carte con
-- la regola della 137 (pagina già nel catalogo → foto vera), anche alla fine di questo file.
--
-- Verificato sul DB il 13/11/2026: i 40 set della 131 hanno 0 righe in set_carte; il vincolo
-- set_carte_codice_check accetta solo lettere e numeri: qui accetta anche "-" e "." (DP-P, CSV9.5C),
-- che il sito e catalogo_cerca già trattano (la chiave del codice toglie spazi e trattini).
-- VA ESEGUITA DOPO sql/137. Rollback: 142_catalogo_asiatici_mfb_ROLLBACK.sql.

begin;

do $$
begin
    if to_regprocedure('public._catalogo_impara(text, text, text, text)') is null then
        raise exception 'Prima va eseguita sql/137_catalogo_impara_dalle_carte.sql';
    end if;
end $$;

alter table public.set_carte drop constraint if exists set_carte_codice_check;
alter table public.set_carte add constraint set_carte_codice_check
  check (codice is null or codice ~ '^[A-Z0-9][A-Z0-9.-]*( [A-Z0-9]+)?$');

