-- set: i nuovi entrano, quelli della 131 prendono il totale delle pagine (il nome resta)
insert into public.set_espansioni (sigla, tcgdex_id, nome, carte_base, carte_totali, data_uscita, lingua, aggiornato_il)
select s.sigla, null, s.nome, null, s.totale, s.data_uscita, s.lingua, now() from _set_142 s
on conflict (sigla) do update set carte_totali = excluded.carte_totali, aggiornato_il = now();

insert into public.set_carte (sigla, numero, variante, nome, cardmarket_id, cardmarket_url, codice)
select s.sigla, p.numero, 'normale', p.nome, p.cardmarket_id,
       'https://www.cardmarket.com/it/Pokemon/Products/Singles/' || p.slug, p.codice
from _set_142 s join _pagine_142 p on p.esp = s.esp
on conflict (sigla, numero, variante) do nothing;

-- le vostre carte di questi set portano la foto vera (regola B della 137)
do $$
declare
    r record;
begin
    for r in select c.codice, c.lingua, c.url, c.immagine from public.carte c
             where split_part(split_part(c.url, '?', 1), '/', 8) in (select esp from _set_142)
             order by c.ultimo_controllo nulls first, c.id loop
        perform public._catalogo_impara(r.codice, r.lingua, r.url, r.immagine);
    end loop;
end $$;

commit;

-- Controllo a occhio dopo l'esecuzione (non cambia niente):
select e.lingua, count(distinct e.sigla) as set_n, count(c.*) as righe, count(c.immagine) as con_foto
from public.set_espansioni e left join public.set_carte c on c.sigla = e.sigla
where e.lingua <> 'INT' or e.sigla = 'MFB'
group by e.lingua order by e.lingua;
